package io.github.turbopro.ism.bootstrap;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.web.server.LocalServerPort;
import java.nio.file.*;
import java.time.Duration;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
class TenantDictionaryBrowserFixture extends TenantDictionaryIT {
 @LocalServerPort int port;
 @Test void serveTwoTenantDictionaryInheritance()throws Exception{Path control=Path.of(System.getProperty("ism.browser.fixture-dir")).toRealPath();var a=fixture();var b=fixture();Files.writeString(control.resolve("fixture.json"),new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(Map.of("tenantCode",a.code(),"otherCode",b.code())));Files.writeString(control.resolve("ready"),"http://127.0.0.1:"+port);long deadline=System.nanoTime()+Duration.ofMinutes(6).toNanos();while(!Files.exists(control.resolve("finish"))&&System.nanoTime()<deadline){assertThat(Files.exists(control.resolve("abort"))).isFalse();Thread.sleep(100);}assertThat(Files.exists(control.resolve("finish"))).isTrue();assertThat(jdbc.queryForObject("SELECT overridden FROM cfg_tenant_dictionary_type WHERE tenant_id=? AND type_code='COMMON_STATUS'",Integer.class,a.tenant())).isZero();assertThat(jdbc.queryForObject("SELECT version FROM cfg_tenant_dictionary_type WHERE tenant_id=? AND type_code='COMMON_STATUS'",Integer.class,a.tenant())).isEqualTo(2);assertThat(jdbc.queryForObject("SELECT overridden FROM cfg_tenant_dictionary_item WHERE tenant_id=? AND type_code='COMMON_STATUS' AND item_code='ACTIVE'",Integer.class,a.tenant())).isZero();assertThat(jdbc.queryForObject("SELECT version FROM cfg_tenant_dictionary_item WHERE tenant_id=? AND type_code='COMMON_STATUS' AND item_code='ACTIVE'",Integer.class,a.tenant())).isEqualTo(2);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM cfg_tenant_dictionary_type WHERE tenant_id=?",Integer.class,b.tenant())).isZero();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM cfg_tenant_dictionary_item WHERE tenant_id=?",Integer.class,b.tenant())).isZero();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM sys_audit_event WHERE tenant_id=? AND action LIKE 'DICTIONARY_%'",Integer.class,a.tenant())).isEqualTo(4);Files.writeString(Path.of("../../output/playwright/dictionaries/browser-database.txt"),"Tenant A name/item overrides and restoration retain increasing revisions; four audit events, no overrides for tenant B. Real UI/API inheritance, unchanged system values, exact replay after dropped response and final database verified.\n");}
}
